    // ─────────── فصل ۱: خانه تسخیرشده ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Haunted House", titlePersian = "خانه تسخیرشده",
        paragraphs = listOf(
            StoryParagraph("124 was spiteful. Full of a baby's venom.", "۱۲۴ کینه‌توز بود. پر از زهر یک نوزاد."),
            StoryParagraph("The women in the house knew it and so did the children.", "زنان خانه می‌دانستند و بچه‌ها هم می‌دانستند."),
            StoryParagraph("For years, each put up with the spite in his own way, but by 1873, Sethe and her daughter Denver were its only victims.", "سال‌ها هر کس به شیوه خودش کینه را تحمل کرد، اما تا ۱۸۷۳، تنها ست و دخترش دنور قربانیانش بودند."),
            StoryParagraph("The house at 124 Bluestone Road, on the outskirts of Cincinnati, Ohio, was haunted by the ghost of a baby.", "خانه ۱۲۴ جاده بلوستون، در حاشیه سینسیناتی، اوهایو، توسط روح یک نوزاد تسخیر شده بود."),
            StoryParagraph("The ghost had no name, or rather it had a name, but nobody used it; they simply called her Beloved.", "روح نامی نداشت، یا بهتر، نامی داشت اما هیچ‌کس از آن استفاده نمی‌کرد؛ تنها دلبند صدایش می‌زدند."),
            StoryParagraph("The ghost threw pots and pans, overturned tables, slammed doors, broke mirrors, and left small handprints in the dust.", "روح قابلمه‌ها و ماهیتابه‌ها را پرت می‌کرد، میزها را واژگون می‌کرد، درها را به هم می‌کوبید، آینه‌ها را می‌شکست و ردپای دست‌های کوچکی در گرد و غبار باقی می‌گذاشت."),
            StoryParagraph("Sethe had stopped trying to make it leave; she had learned to live with it, as she had learned to live with everything else.", "ست تلاش برای بیرون راندنش را رها کرده بود؛ آموخته بود با آن زندگی کند، همانطور که با هر چیز دیگری زندگی کردن را آموخته بود."),
            StoryParagraph("Denver, who was eighteen, was lonely and afraid; she had no friends, no life outside the house, no hope of anything more.", "دنور که هجده ساله بود، تنها و ترسیده بود؛ دوستی نداشت، زندگی‌ای بیرون از خانه نداشت، امیدی به چیزی بیشتر نداشت."),
            StoryParagraph("She spent her days in the yard, by the tree, dreaming of a past she barely remembered and a future she could not imagine.", "روزهایش را در حیاط، کنار درخت می‌گذراند، در خواب گذشته‌ای که به‌سختی به یاد می‌آورد و آینده‌ای که نمی‌توانست تصور کند."),
            StoryParagraph("Her two older brothers, Howard and Buglar, had run away years ago, driven out by the ghost.", "دو برادر بزرگ‌ترش، هاوارد و باگلار، سال‌ها پیش فرار کرده بودند، توسط روح رانده شده بودند."),
            StoryParagraph("They had waited until Sethe was out of the house, and then they had packed their things and left.", "منتظر مانده بودند تا ست از خانه بیرون برود و بعد وسایلشان را بسته و رفته بودند."),
            StoryParagraph("They had not said goodbye; they had simply gone; and Sethe had never heard from them again.", "خداحافظی نکرده بودند؛ تنها رفته بودند؛ و ست هرگز دوباره از آن‌ها خبری نگرفت."),
            StoryParagraph("Their grandmother, Baby Suggs, had died before they left; she had simply gone to bed one day and not gotten up.", "مادربزرگشان بیبی ساگز، پیش از رفتنشان مرده بود؛ تنها یک روز به رختخواب رفته بود و بلند نشده بود."),
            StoryParagraph("Baby Suggs had been a preacher, a woman of great faith and greater love; she had gathered the Black community around her, and she had taught them to love their bodies, their souls, their lives.", "بیبی ساگز واعظی بود، زنی با ایمان فراوان و عشق بیشتر؛ جامعه سیاه‌پوستان را دور خودش جمع کرده بود و به آنان آموخته بود بدن‌هایشان را دوست بدارند، روح‌هایشان، زندگی‌شان."),
            StoryParagraph("She had taught them to laugh, to cry, to dance, to sing; she had taught them to be free, in a world that wanted them enslaved.", "به آنان آموخته بود بخندند، گریه کنند، برقصند، بخوانند؛ آموخته بود آزاد باشند، در جهانی که می‌خواست آن‌ها را برده کند."),
            StoryParagraph("And then, one day, she had simply stopped; she had lain down in her bed, and she had not gotten up, and she had died within a week.", "و بعد، یک روز، تنها ایستاده بود؛ در تختش دراز کشیده بود و بلند نشده بود و در عرض یک هفته مرده بود."),
            StoryParagraph("Sethe missed her every day; she missed her counsel, her warmth, her love; she missed the only person who had ever truly understood her.", "ست هر روز دلتنگش بود؛ دلتنگ مشورتش بود، گرمی‌اش، عشقش؛ دلتنگ تنها کسی بود که هرگز به‌راستی درکش کرده بود."),
            StoryParagraph("Sethe was a woman of iron will and iron sorrow; she had been a slave, and she had escaped, and she had paid a terrible price for her freedom.", "ست زنی با اراده آهنین و اندوه آهنین بود؛ برده بوده و فرار کرده و بهای هولناکی برای آزادی‌اش پرداخته بود."),
            StoryParagraph("She had sent her children ahead, on the Underground Railroad, and then she had run, alone, pregnant, her back torn open by whips, her feet bleeding, her heart breaking.", "بچه‌هایش را پیشاپیش فرستاده بود، در راه‌آهن زیرزمینی و بعد فرار کرده بود، تنها، باردار، پشتش توسط شلاق دریده، پاهایش خونریزی داشتند، قلبش شکسته بود."),
            StoryParagraph("She had reached Ohio, reached freedom, reached her children; and then they had come for her, the slave catchers, with their dogs and their guns and their papers.", "به اوهایو رسیده بود، به آزادی، به بچه‌هایش؛ و بعد برایش آمده بودند، شکارچیان برده، با سگ‌هایشان و تفنگ‌هایشان و کاغذهایشان."),
            StoryParagraph("And she had done something, something terrible, something that no one could ever forget.", "و کاری کرده بود، کاری هولناک، کاری که هیچ‌کس نمی‌توانست فراموشش کند."),
            StoryParagraph("She had killed her baby daughter.", "دختر نوزادش را کشته بود."),
            StoryParagraph("She had cut her throat with a handsaw, in the shed behind the house, while the slave catchers broke down the door.", "گلویش را با اره‌ای در انبار پشت خانه بریده بود، در حالی که شکارچیان برده در را می‌شکستند."),
            StoryParagraph("She had not wanted her daughter to be a slave.", "نمی‌خواست دخترش برده شود."),
            StoryParagraph("She had not wanted her daughter to know what she had known, to suffer what she had suffered, to lose what she had lost.", "نمی‌خواست دخترش آنچه را که او شناخته بود بداند، آنچه را که او کشیده بود بکشد، آنچه را که او از دست داده بود از دست بدهد."),
            StoryParagraph("She had wanted to save her, in the only way she knew how.", "می‌خواست نجاتش دهد، به تنها شیوه‌ای که می‌دانست."),
            StoryParagraph("She had carved the word 'Beloved' on the tombstone, and she had paid for it with her body, giving herself to the stonecutter for ten minutes.", "کلمه «دلبند» را روی سنگ قبر حک کرده بود و با بدنش هزینه‌اش را پرداخته بود، خودش را به مدت ده دقیقه به سنگ‌تراش داده بود."),
            StoryParagraph("She had buried the baby, and she had mourned, and she had gone on, because she had to, because there was no other choice.", "نوزاد را دفن کرده بود و عزاداری کرده بود و ادامه داده بود، چون مجبور بود، چون انتخاب دیگری نبود."),
            StoryParagraph("And ever since, the ghost had haunted her.", "و از آن زمان، روح تسخیرش می‌کرد."),
            StoryParagraph("The ghost of her baby, the ghost of her love, the ghost of her crime.", "روح نوزادش، روح عشقش، روح جنایتش."),
            StoryParagraph("It was 1873 now, ten years after the war, ten years after Emancipation, ten years after everything had supposedly changed.", "حالا ۱۸۷۳ بود، ده سال بعد از جنگ، ده سال بعد از آزادی، ده سال بعد از آنکه همه چیز گویا تغییر کرده بود."),
            StoryParagraph("But for Sethe, nothing had changed; she was still trapped in the past, still haunted by what she had done, still unable to move forward.", "اما برای ست، هیچ چیز تغییر نکرده بود؛ هنوز در گذشته گرفتار بود، هنوز توسط آنچه کرده بود تسخیر می‌شد، هنوز ناتوان از حرکت به جلو."),
            StoryParagraph("And so she lived, day after day, in the haunted house at 124, with her daughter Denver, and with the ghost of the baby she had killed.", "و اینگونه زندگی می‌کرد، روز پس از روز، در خانه تسخیرشده در ۱۲۴، با دخترش دنور و با روح نوزادی که کشته بود."),
            StoryParagraph("Until one day, a man arrived, a man from her past, a man named Paul D.", "تا یک روز، مردی رسید، مردی از گذشته‌اش، مردی به نام پاول دی."),
            StoryParagraph("And with his arrival, everything changed.", "و با ورودش، همه چیز تغییر کرد."),
            StoryParagraph("The ghost was chased away; the doors were opened; the windows were thrown wide.", "روح فراری داده شد؛ درها باز شدند؛ پنجره‌ها باز شدند."),
            StoryParagraph("And for a time, there was peace at 124 Bluestone Road.", "و برای مدتی، صلح در ۱۲۴ جاده بلوستون برقرار شد."),
            StoryParagraph("But peace, in Sethe's life, was never meant to last.", "اما صلح، در زندگی ست، قرار نبود دوام بیاورد."),
            StoryParagraph("And so began the story of Beloved, the story of a haunted house, a haunted family, a haunted nation.", "و اینگونه داستان دلبند آغاز شد، داستان خانه‌ای تسخیرشده، خانواده‌ای تسخیرشده، ملتی تسخیرشده.")
        )
    )

    // ─────────── فصل ۲: پاول دی ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Paul D", titlePersian = "پاول دی",
        paragraphs = listOf(
            StoryParagraph("Paul D arrived at 124 Bluestone Road on a Sunday afternoon in 1873, walking up the path like a man who had been walking for years.", "پاول دی در بعدازظهری یکشنبه در ۱۸۷۳ به ۱۲۴ جاده بلوستون رسید، در مسیر راه می‌رفت مثل مردی که سال‌ها راه رفته بود."),
            StoryParagraph("He was lean and strong, with a face that had known weather and hunger and pain.", "لاغر و قوی بود، با چهره‌ای که آب و هوا و گرسنگی و درد را می‌شناخت."),
            StoryParagraph("He carried a small bag, and he walked with the slow, steady gait of a man who had traveled thousands of miles on foot.", "کیسه‌ای کوچک حمل می‌کرد و با قدمی آهسته و ثابت راه می‌رفت، همچون مردی که هزاران مایل پیاده سفر کرده بود."),
            StoryParagraph("He had been walking since the end of the war, since Emancipation, since freedom had come and he had not known what to do with it.", "از پایان جنگ راه می‌رفت، از آزادی، از وقتی که آزادی آمده بود و نمی‌دانست با آن چه کند."),
            StoryParagraph("He had been a slave at Sweet Home, in Kentucky, the same plantation where Sethe had lived, the same plantation where Sethe had fled from.", "در خانه شیرین، در کنتاکی، برده بوده، همان مزرعه‌ای که ست در آن زندگی کرده بود، همان مزرعه‌ای که ست از آن فرار کرده بود."),
            StoryParagraph("He had known Sethe there, had loved her there, had wanted her there; but she had belonged to another man, or so he had thought.", "آنجا ست را شناخته بود، آنجا دوستش داشته بود، آنجا خواسته بودش؛ اما او مال مرد دیگری بود، یا اینطور فکر می‌کرد."),
            StoryParagraph("That other man was Halle Suggs, the son of Baby Suggs, the man who had bought Sethe's freedom, the man who had fathered her children.", "آن مرد دیگر هال ساگز بود، پسر بیبی ساگز، مردی که آزادی ست را خریده بود، مردی که پدر بچه‌هایش بود."),
            StoryParagraph("Halle had loved Sethe with all his heart; and Sethe had loved him, or had come to love him, in the slow, patient way that love sometimes grows.", "هال ست را با تمام قلبش دوست داشت؛ و ست او را دوست داشت، یا شروع کرده بود به دوست داشتنش، به شیوه آهسته و صبورانه‌ای که عشق گاهی رشد می‌کند."),
            StoryParagraph("But Halle had gone mad, in the end; he had seen something, in the barn at Sweet Home, something that had broken him.", "اما هال در نهایت دیوانه شده بود؛ چیزی در انبار خانه شیرین دیده بود، چیزی که شکسته بودش."),
            StoryParagraph("He had seen the men of Sweet Home take Sethe's milk, take it from her breasts, take it with their hands and their mouths, while she screamed and begged.", "دیده بود مردان خانه شیرین شیر ست را می‌گرفتند، از سینه‌هایش می‌گرفتند، با دستان و دهانشان می‌گرفتند، در حالی که او فریاد می‌زد و التماس می‌کرد."),
            StoryParagraph("That was the last thing Halle saw, or the last thing he was able to bear; after that, he was gone, disappeared, dead or mad, no one ever knew.", "این آخرین چیزی بود که هال دید، یا آخرین چیزی که توانست تحمل کند؛ بعد از آن، رفته بود، ناپدید شده، مرده یا دیوانه، هیچ‌کس هرگز ندانست."),
            StoryParagraph("Paul D had not seen Halle since that day; but he had seen Sethe, had seen her run, had seen her escape, had seen her reach freedom.", "پاول دی از آن روز هال را ندیده بود؛ اما ست را دیده بود، دیده بود فرار می‌کند، دیده بود می‌گریزد، دیده بود به آزادی می‌رسد."),
            StoryParagraph("And now, years later, he had found her again.", "و حالا، سال‌ها بعد، دوباره پیدایش کرده بود."),
            StoryParagraph("'Sethe,' he said, when she opened the door, and his voice was low and careful, as if he were afraid of breaking something.", "وقتی در را باز کرد گفت: «ست.» و صدایش پایین و محتاط بود، گویی می‌ترسید چیزی را بشکند."),
            StoryParagraph("'Paul D,' she said, and her voice was careful too, and her eyes were full of something that might have been joy and might have been fear.", "گفت: «پاول دی.» و صدایش محتاط بود و چشمانش پر از چیزی بود که می‌توانست شادی باشد یا ترس."),
            StoryParagraph("They stood there for a long moment, not moving, not speaking, just looking at each other, two survivors of a nightmare that had ended years ago but that had never really ended.", "لحظه‌ای طولانی آنجا ایستادند، بدون حرکت، بدون سخن، تنها به هم نگاه می‌کردند، دو بازمانده از کابوسی که سال‌ها پیش تمام شده بود اما هرگز واقعاً تمام نشده بود."),
            StoryParagraph("And then Sethe stepped aside, and Paul D entered the house, and the door closed behind him.", "و بعد ست کنار رفت و پاول دی وارد خانه شد و در پشتش بسته شد."),
            StoryParagraph("Inside, the house was quiet; the ghost had not yet made itself known; it was waiting, watching, preparing to act.", "درون، خانه ساکت بود؛ روح هنوز خودش را نشان نداده بود؛ منتظر بود، تماشا می‌کرد، آماده می‌شد عمل کند."),
            StoryParagraph("Denver came out of her room to see who had come, and she saw Paul D, and she was afraid.", "دنور از اتاقش بیرون آمد که ببیند چه کسی آمده و پاول دی را دید و ترسید."),
            StoryParagraph("She had never met a man, not since her brothers had left, not since her father had disappeared; and she did not know what to make of this one.", "هرگز مردی ملاقات نکرده بود، نه از وقتی برادرانش رفته بودند، نه از وقتی پدرش ناپدید شده بود؛ و نمی‌دانست با این یکی چه کند."),
            StoryParagraph("But Paul D was kind to her; he spoke softly, he smiled gently, he did not demand anything.", "اما پاول دی با او مهربان بود؛ آرام صحبت کرد، لطیف لبخند زد، چیزی طلب نکرد."),
            StoryParagraph("And slowly, over the next few days, Denver began to trust him, to like him, to hope that he might stay.", "و آهسته، در طول چند روز بعد، دنور شروع کرد به اعتماد به او، به دوست داشتنش، به امید اینکه شاید بماند."),
            StoryParagraph("Paul D did stay; he stayed because he had nowhere else to go, and because he had found Sethe at last, and because he loved her still.", "پاول دی ماند؛ ماند چون جای دیگری نداشت برود و چون سرانجام ست را یافته بود و چون هنوز دوستش داشت."),
            StoryParagraph("He stayed, and he slept in the house, and he helped with the chores, and slowly, he became part of the family.", "ماند و در خانه خوابید و در کارها کمک کرد و آرام‌آرام، بخشی از خانواده شد."),
            StoryParagraph("But the ghost did not like this; the ghost did not want to share Sethe with anyone.", "اما روح این را دوست نداشت؛ روح نمی‌خواست ست را با کسی قسمت کند."),
            StoryParagraph("One night, the ghost threw a table across the room; it slammed doors, it broke dishes, it screamed in the darkness.", "یک شب، روح میزی را به آنسوی اتاق پرت کرد؛ درها را کوبید، ظرف‌ها را شکست، در تاریکی فریاد زد."),
            StoryParagraph("Paul D had had enough; he had faced worse things than ghosts; he had faced slavery, and war, and hunger, and death.", "پاول دی به اندازه کافی تحمل کرده بود؛ با چیزهای بدتر از روح روبرو شده بود؛ با بردگی روبرو شده بود و جنگ و گرسنگی و مرگ."),
            StoryParagraph("He stood in the middle of the room, and he shouted at the ghost, and he told it to leave, and he told it to never come back.", "در وسط اتاق ایستاد و بر سر روح فریاد زد و به آن گفت برود و گفت هرگز برنگردد."),
            StoryParagraph("And the ghost, surprised perhaps, or afraid, or simply tired of fighting, obeyed.", "و روح، شاید حیرت‌زده، یا ترسیده، یا تنها خسته از جنگیدن، اطاعت کرد."),
            StoryParagraph("The house fell silent; the table stayed in its place; the doors stayed shut; the darkness was quiet.", "خانه ساکت شد؛ میز سر جایش ماند؛ درها بسته ماندند؛ تاریکی ساکت شد."),
            StoryParagraph("And for a time, there was peace at 124 Bluestone Road.", "و برای مدتی، صلح در ۱۲۴ جاده بلوستون برقرار شد."),
            StoryParagraph("Sethe began to heal; she began to hope; she began to believe that the past was the past, and that the future might be different.", "ست شروع کرد به شفا یافتن؛ شروع کرد به امید داشتن؛ شروع کرد به باور اینکه گذشته، گذشته است و آینده ممکن است متفاوت باشد."),
            StoryParagraph("She and Paul D talked, in the evenings, about the old days; they talked about Sweet Home, about Halle, about the others.", "او و پاول دی در عصرها صحبت می‌کردند، درباره روزهای قدیم؛ از خانه شیرین می‌گفتند، از هال، از دیگران."),
            StoryParagraph("They talked about the men who had owned them, and the men who had used them, and the men who had destroyed them.", "از مردانی می‌گفتند که مالکشان بودند و مردانی که از آنان استفاده کردند و مردانی که نابودشان کردند."),
            StoryParagraph("And they talked about the future, about what they might build, about the life they might live together.", "و از آینده می‌گفتند، از آنچه می‌توانستند بسازند، از زندگی‌ای که می‌توانستند با هم داشته باشند."),
            StoryParagraph("Denver watched them, and she was happy; she had never seen her mother smile so much, laugh so much, hope so much.", "دنور تماشایشان کرد و خوشحال بود؛ هرگز ندیده بود مادرش اینقدر لبخند بزند، اینقدر بخندد، اینقدر امید داشته باشد."),
            StoryParagraph("And so, for a season, there was joy at 124 Bluestone Road.", "و اینگونه، برای فصلی، شادی در ۱۲۴ جاده بلوستون بود."),
            StoryParagraph("But the past, Sethe would learn, does not stay in the past; it returns, it always returns, and it demands to be faced.", "اما گذشته، ست می‌آموخت، در گذشته نمی‌ماند؛ برمی‌گردد، همیشه برمی‌گردد و می‌طلبد که با آن روبرو شوی."),
            StoryParagraph("And one day, on a hot afternoon in late summer, a young woman appeared at the end of the path, walking slowly, uncertainly, toward the house.", "و یک روز، در بعدازظهری گرم در اواخر تابستان، زنی جوان در انتهای مسیر ظاهر شد، آهسته و نامطمئن، به سمت خانه راه می‌رفت."),
            StoryParagraph("She was barefoot; her dress was clean but old; her skin was smooth and strange; her eyes were dark and empty.", "پابرهنه بود؛ لباسش تمیز اما کهنه بود؛ پوستش صاف و عجیب بود؛ چشمانش تیره و خالی."),
            StoryParagraph("She came to the door, and she stood there, and she said a single word.", "به در آمد و آنجا ایستاد و کلمه‌ای واحد گفت."),
            StoryParagraph("'Beloved,' she said.", "گفت: «دلبند.»")
        )
    )

    // ─────────── فصل ۳: دلبند ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Beloved", titlePersian = "دلبند",
        paragraphs = listOf(
            StoryParagraph("The young woman who called herself Beloved had no past; she remembered nothing before the moment she appeared at the end of the path.", "زن جوانی که خود را دلبند می‌نامید گذشته‌ای نداشت؛ قبل از لحظه‌ای که در انتهای مسیر ظاهر شد چیزی به یاد نمی‌آورد."),
            StoryParagraph("She could not say where she had come from, or who her parents were, or how old she was.", "نمی‌توانست بگوید از کجا آمده، یا پدر و مادرش کیستند، یا چند ساله است."),
            StoryParagraph("She could not say why she had come to 124 Bluestone Road, or how she knew the word 'Beloved,' or what she wanted.", "نمی‌توانست بگوید چرا به ۱۲۴ جاده بلوستون آمده، یا از کجا کلمه «دلبند» را می‌داند، یا چه می‌خواهد."),
            StoryParagraph("She was like a child, in some ways; she needed to be fed, to be bathed, to be watched over; she could not take care of herself.", "از برخی جهات مثل بچه بود؛ باید غذا داده می‌شد، شسته می‌شد، مراقبت می‌شد؛ نمی‌توانست از خودش مراقبت کند."),
            StoryParagraph("But she was also like a woman, in other ways; her body was mature, her eyes were ancient, her presence was overwhelming.", "اما از جهات دیگر مثل زن بود؛ بدنش بالغ، چشمانش کهن، حضورش طاقت‌فرسا."),
            StoryParagraph("Sethe took her in, as she would have taken in any lost soul; she fed her, clothed her, gave her a bed.", "ست پذیرفتش، همانطور که هر روح گمگشته‌ای را می‌پذیرفت؛ غذا داد، لباس داد، تختی داد."),
            StoryParagraph("But from the very first moment, Sethe felt a strange connection to the young woman; she felt that she knew her, that she had always known her.", "اما از همان نخستین لحظه، ست ارتباطی عجیب با آن زن جوان حس کرد؛ حس کرد می‌شناسدش، همیشه می‌شناخته."),
            StoryParagraph("The young woman called herself Beloved, and she seemed to want nothing except to be near Sethe.", "زن جوان خود را دلبند می‌نامید و به نظر می‌رسید تنها چیزی که می‌خواهد نزدیک بودن به ست است."),
            StoryParagraph("She followed Sethe everywhere, she watched Sethe constantly, she touched Sethe whenever she could.", "همه‌جا ست را دنبال می‌کرد، مدام تماشایش می‌کرد، هر وقت می‌توانست لمسش می‌کرد."),
            StoryParagraph("She loved Sethe with an intensity that was almost frightening; she wanted all of Sethe's attention, all of Sethe's love, all of Sethe's time.", "ست را با شدتی دوست داشت که تقریباً هراس‌آور بود؛ تمام توجه ست را می‌خواست، تمام عشقش، تمام وقتش."),
            StoryParagraph("Denver, at first, was happy; she had a sister now, a companion, someone to share her loneliness.", "دنور اول خوشحال بود؛ حالا خواهری داشت، همراهی، کسی که تنهایی‌اش را قسمت کند."),
            StoryParagraph("But soon she began to feel uneasy; there was something wrong with Beloved, something unnatural, something that Denver could sense but not name.", "اما به‌زودی شروع کرد به حس ناآرامی؛ چیزی در دلبند اشتباه بود، چیزی غیرطبیعی، چیزی که دنور می‌توانست حس کند اما نامش را نبرد."),
            StoryParagraph("Beloved did not eat like other people; she ate only sweets, only cakes, only sugar; she refused meat, vegetables, bread.", "دلبند مثل دیگران غذا نمی‌خورد؛ تنها شیرینی می‌خورد، تنها کیک، تنها شکر؛ گوشت را رد می‌کرد، سبزیجات، نان."),
            StoryParagraph("She did not sleep like other people; she slept with her eyes open, and she never seemed tired, never seemed rested.", "مثل دیگران نمی‌خوابید؛ با چشمان باز می‌خوابید و هرگز خسته به نظر نمی‌رسید، هرگز آسوده."),
            StoryParagraph("She did not speak like other people; her voice was strange, her words were strange, her silences were stranger still.", "مثل دیگران صحبت نمی‌کرد؛ صدایش عجیب بود، کلماتش عجیب، سکوت‌هایش عجیب‌تر."),
            StoryParagraph("And she had a scar on her neck, a thin line, like a cut that had healed but not faded.", "و زخمی بر گردنش داشت، خطی نازک، مثل برشی که شفا یافته اما محو نشده."),
            StoryParagraph("Sethe saw the scar, and she remembered; she remembered the handsaw, the shed, the blood, the baby.", "ست زخم را دید و به یاد آورد؛ به یاد آورد اره را، انبار را، خون را، نوزاد را."),
            StoryParagraph("And she knew, with a certainty that she could not explain, that the young woman was her daughter.", "و دانست، با یقینی که نمی‌توانست توضیح دهد، که آن زن جوان دخترش است."),
            StoryParagraph("Her daughter, returned from the dead; her daughter, come back to her; her daughter, the one she had killed, the one she had loved, the one she had lost.", "دخترش، بازگشته از مردگان؛ دخترش، برگشته پیش او؛ دخترش، همان که کشته بود، همان که دوست داشت، همان که از دست داده بود."),
            StoryParagraph("And Sethe, who had never forgiven herself, who had never stopped mourning, who had never stopped hoping, felt something that she had not felt in years: joy.", "و ست که هرگز خودش را نبخشیده بود، هرگز از سوگواری دست نکشیده بود، هرگز از امید دست نکشیده بود، چیزی حس کرد که سال‌ها حس نکرده بود: شادی."),
            StoryParagraph("But Paul D did not feel joy; he felt fear; he felt that something was wrong, deeply wrong, dangerously wrong.", "اما پاول دی شادی حس نکرد؛ ترس حس کرد؛ حس کرد چیزی اشتباه است، به‌طور عمیقی اشتباه، به‌طور خطرناکی اشتباه."),
            StoryParagraph("'That girl,' he said to Sethe, one night, 'that girl is not right. She is not like us.'", "یک شب به ست گفت: «آن دختر درست نیست. مثل ما نیست.»"),
            StoryParagraph("'She is my daughter,' Sethe said, and her voice was fierce. 'She came back to me. She came back.'", "ست گفت: «دختر من است.» و صدایش خشمگین بود. «بازگشت پیش من. بازگشت.»"),
            StoryParagraph("'Sethe,' Paul D said, quietly, 'you cannot know that. You cannot know what she is.'", "پاول دی آرام گفت: «ست، نمی‌توانی بدانی. نمی‌توانی بدانی چیست.»"),
            StoryParagraph("'I know,' Sethe said. 'I know in my heart. She is my Beloved. She came back.'", "ست گفت: «می‌دانم. در قلبم می‌دانم. او دلبندم است. بازگشت.»"),
            StoryParagraph("And there was nothing Paul D could say, nothing he could do; Sethe was lost in her love for the girl, in her hope, in her delusion.", "و پاول دی هیچ نمی‌توانست بگوید، هیچ کاری نمی‌توانست بکند؛ ست در عشقش به آن دختر گم شده بود، در امیدش، در توهمش."),
            StoryParagraph("Beloved grew stronger every day; she grew larger, hungrier, more demanding; she ate and ate and was never satisfied.", "دلبند هر روز قوی‌تر می‌شد؛ بزرگ‌تر، گرسنه‌تر، پرتوقع‌تر؛ می‌خورد و می‌خورد و هرگز سیر نمی‌شد."),
            StoryParagraph("She demanded all of Sethe's time, all of Sethe's attention, all of Sethe's love; and Sethe gave her everything, gave her everything and more.", "تمام وقت ست را می‌خواست، تمام توجهش، تمام عشقش؛ و ست همه چیز به او داد، همه چیز و بیشتر."),
            StoryParagraph("Sethe stopped going to work; she stopped cooking for Paul D and Denver; she stopped caring for herself.", "ست از رفتن به کار دست کشید؛ از پختن برای پاول دی و دنور دست کشید؛ از مراقبت از خودش دست کشید."),
            StoryParagraph("She devoted herself entirely to Beloved, to the daughter she had killed, to the daughter she had loved, to the daughter she could not let go.", "خودش را کاملاً وقف دلبند کرد، دختری که کشته بود، دختری که دوست داشت، دختری که نمی‌توانست رهایش کند."),
            StoryParagraph("Paul D tried to intervene; he tried to reason with her; he tried to save her.", "پاول دی تلاش کرد دخالت کند؛ تلاش کرد با او منطقی صحبت کند؛ تلاش کرد نجاتش دهد."),
            StoryParagraph("But Beloved hated Paul D; Beloved wanted him gone; Beloved used her strange power to drive a wedge between him and Sethe.", "اما دلبند از پاول دی متنفر بود؛ دلبند می‌خواست برود؛ دلبند از قدرت عجیبش استفاده کرد تا گوه‌ای بین او و ست بیندازد."),
            StoryParagraph("One night, Beloved came to Paul D's bed; she offered herself to him; she tempted him, and he, weak and human, gave in.", "یک شب دلبند به تخت پاول دی آمد؛ خودش را به او عرضه کرد؛ وسوسه‌اش کرد و او، ضعیف و انسانی، تسلیم شد."),
            StoryParagraph("And then she told Sethe what had happened; and Sethe, hurt and betrayed, turned on Paul D.", "و بعد به ست گفت چه اتفاقی افتاده؛ و ست، زخمی و خیانت‌دیده، به پاول دی حمله کرد."),
            StoryParagraph("'You touched her,' Sethe cried. 'You touched my daughter.'", "ست فریاد زد: «لمسش کردی. دخترم را لمس کردی.»"),
            StoryParagraph("'She came to me,' Paul D said. 'She came to me, Sethe. I did not—'", "پاول دی گفت: «او پیش من آمد. او پیش من آمد، ست. من—»"),
            StoryParagraph("'Get out,' Sethe said. 'Get out of my house. Get out of my life. Get out.'", "ست گفت: «برو بیرون. از خانه‌ام برو. از زندگی‌ام برو. برو.»"),
            StoryParagraph("And Paul D, who had loved her, who had tried to save her, who had tried to build a life with her, walked out the door, and did not come back.", "و پاول دی که دوستش داشت، که تلاش کرده بود نجاتش دهد، که تلاش کرده بود با او زندگی بسازد، از در بیرون رفت و بازنگشت."),
            StoryParagraph("And so Beloved, the ghost made flesh, the daughter made real, took Sethe's love and Sethe's life and Sethe's soul, and consumed them all.", "و اینگونه دلبند، روح جسم‌گرفته، دختر واقعی‌شده، عشق ست را گرفت و زندگی‌اش و روحش و همه‌شان را بلعید.")
        )
    )

    // ─────────── فصل ۴: جامعه ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Community", titlePersian = "جامعه",
        paragraphs = listOf(
            StoryParagraph("Denver, who had watched everything, who had seen her mother destroyed by Beloved, realized at last that she had to act.", "دنور که همه چیز را تماشا کرده بود، که دیده بود مادرش توسط دلبند نابود می‌شود، سرانجام فهمید باید کاری کند."),
            StoryParagraph("She had been afraid to leave the house for years, afraid of the world beyond the gate, afraid of the people who had judged her mother.", "سال‌ها از ترک خانه می‌ترسید، از جهان آنسوی در، از مردمی که مادرش را قضاوت کرده بودند."),
            StoryParagraph("But she was more afraid of what was happening inside the house; she was more afraid of losing her mother to the ghost.", "اما بیشتر از آنچه درون خانه می‌گذشت می‌ترسید؛ بیشتر از از دست دادن مادرش به دست روح می‌ترسید."),
            StoryParagraph("So she put on her shoes, and she put on her coat, and she walked out the door, out the gate, down the road, into the world.", "پس کفش‌هایش را پوشید و پالتویش را و از در بیرون رفت، از دروازه، از جاده، به جهان."),
            StoryParagraph("She went to the neighbors, to the women of the Black community, to the same women who had once rejected her mother.", "به همسایه‌ها رفت، به زنان جامعه سیاه‌پوستان، به همان زنانی که یک بار مادرش را طرد کرده بودند."),
            StoryParagraph("The community had turned against Sethe years before, after she had killed her baby; they had judged her, condemned her, cast her out.", "جامعه سال‌ها پیش علیه ست شده بود، بعد از اینکه نوزادش را کشت؛ قضاوتش کرده بودند، محکومش کرده بودند، طردش کرده بودند."),
            StoryParagraph("They had said that she had done wrong, that she had sinned, that she had gone too far.", "گفته بودند کار اشتباهی کرده، گناه کرده، بیش از حد رفته."),
            StoryParagraph("They had said that no mother should kill her child, no matter the reason, no matter the pain.", "گفته بودند هیچ مادری نباید بچه‌اش را بکشد، هر چه دلیل، هر چه درد."),
            StoryParagraph("But they had also understood, in their hearts, what Sethe had done, and why; they had also known the horror of slavery, and the terror of losing a child to it.", "اما در دلشان هم فهمیده بودند ست چه کرده و چرا؛ هولناکی بردگی را هم می‌دانستند و وحشت از دست دادن بچه به آن را."),
            StoryParagraph("They had been divided between judgment and compassion, between anger and understanding.", "بین قضاوت و شفقت تقسیم شده بودند، بین خشم و فهم."),
            StoryParagraph("And now, years later, Denver came to them, and she asked for help.", "و حالا، سال‌ها بعد، دنور به نزدشان آمد و کمک خواست."),
            StoryParagraph("'Please,' she said. 'Please help us. My mother is dying.'", "گفت: «لطفاً. لطفاً کمکمان کنید. مادرم دارد می‌میرد.»"),
            StoryParagraph("The women listened, and they looked at each other, and they remembered.", "زنان گوش دادند و به هم نگاه کردند و به یاد آوردند."),
            StoryParagraph("They remembered Baby Suggs, who had loved them all, who had taught them to love themselves.", "بیبی ساگز را به یاد آوردند، که همه‌شان را دوست داشت، که به آنان آموخته بود خودشان را دوست بدارند."),
            StoryParagraph("They remembered Sethe, who had been Baby Suggs's daughter-in-law, who had been one of them.", "ست را به یاد آوردند، که عروس بیبی ساگز بوده، که یکی از آنان بوده."),
            StoryParagraph("They remembered the horror that had driven her to do what she had done; they remembered the world that had made such horror possible.", "هولناکی‌ای را به یاد آوردند که او را به آنچه کرده بود رانده بود؛ جهانی را به یاد آوردند که چنین هولناکی را ممکن کرده بود."),
            StoryParagraph("And they decided, at last, to help.", "و سرانجام تصمیم گرفتند کمک کنند."),
            StoryParagraph("Thirty women, Black women, women of all ages, gathered on the road in front of 124 Bluestone Road.", "سی زن، زنان سیاه‌پوست، زنان از همه سنین، در جاده پیش روی ۱۲۴ جاده بلوستون جمع شدند."),
            StoryParagraph("They came with their Bibles, their rosaries, their hymns; they came with their love, their anger, their hope.", "با انجیل‌هایشان آمدند، تسبیح‌هایشان، سرودهایشان؛ با عشقشان آمدند، خشمشان، امیدشان."),
            StoryParagraph("And they began to pray, and they began to sing, and their voices rose into the air, filling the afternoon.", "و شروع کردند به دعا خواندن و شروع کردند به خواندن و صدایشان در هوا بلند شد، بعدازظهر را پر کرد."),
            StoryParagraph("The sound was like a wave, like a storm, like a river in flood; it swept through the house, through the rooms, through the souls of everyone inside.", "صدا مثل موجی بود، مثل طوفانی، مثل رودی در طغیان؛ خانه را درنوردید، اتاق‌ها را، روح همه کسانی که درون بودند."),
            StoryParagraph("Sethe, who was lying in bed, too weak to move, heard the singing, and she thought that it was the voice of her mother, come to take her home.", "ست که در تخت دراز کشیده بود، بسیار ضعیف که نمی‌توانست حرکت کند، آواز را شنید و فکر کرد صدای مادرش است، آمده که او را به خانه ببرد."),
            StoryParagraph("Beloved, who was standing by the window, heard the singing, and she began to shake; she began to scream; she began to dissolve.", "دلبند که کنار پنجره ایستاده بود، آواز را شنید و شروع کرد به لرزیدن؛ شروع کرد به فریاد زدن؛ شروع کرد به حل شدن."),
            StoryParagraph("Because the singing was the voice of the community, the voice of the living, the voice of the world; and Beloved was not of that world, not anymore.", "زیرا آواز صدای جامعه بود، صدای زندگان، صدای جهان؛ و دلبند از آن جهان نبود، دیگر نبود."),
            StoryParagraph("She had been dead, and she had come back, but she could not stay; the world did not have room for her, and she could not make room for herself.", "مرده بود و بازگشته بود اما نمی‌توانست بماند؛ جهان جایی برایش نداشت و او نمی‌توانست جایی برای خودش بسازد."),
            StoryParagraph("The women came to the door, and they opened it, and they entered the house.", "زنان به در آمدند و بازش کردند و وارد خانه شدند."),
            StoryParagraph("They found Sethe in bed, and they found Beloved by the window, and they found Denver standing between them, and they saw everything.", "ست را در تخت یافتند و دلبند را کنار پنجره و دنور را که بینشان ایستاده بود و همه چیز را دیدند."),
            StoryParagraph("And they did what they had come to do; they prayed over Sethe, and they sang over Beloved, and they called on the spirit of Baby Suggs to help them.", "و آنچه آمده بودند بکنند کردند؛ بر ست دعا خواندند و بر دلبند خواندند و روح بیبی ساگز را به کمک خواندند."),
            StoryParagraph("And slowly, slowly, Beloved began to fade; she began to grow smaller, weaker, paler; she began to return to wherever she had come from.", "و آهسته، آهسته، دلبند شروع کرد به محو شدن؛ شروع کرد به کوچک‌تر شدن، ضعیف‌تر، رنگ‌پریده‌تر؛ شروع کرد به بازگشتن به هر جایی که از آن آمده بود."),
            StoryParagraph("She stood by the window, in the morning light, and she looked at Sethe, and she said a single word.", "کنار پنجره ایستاد، در نور صبح و به ست نگاه کرد و کلمه‌ای واحد گفت."),
            StoryParagraph("'Beloved,' she said, and then she was gone.", "گفت: «دلبند.» و بعد رفت."),
            StoryParagraph("She was gone, and the house was quiet, and the women stood in silence, and no one said anything.", "رفته بود و خانه ساکت بود و زنان در سکوت ایستادند و هیچ‌کس چیزی نگفت."),
            StoryParagraph("Sethe, who had been lying in bed, who had been dying, who had been lost, opened her eyes, and she looked around, and she asked a question.", "ست که در تخت دراز کشیده بود، که در حال مرگ بود، که گم شده بود، چشمانش را باز کرد و اطراف را نگاه کرد و پرسشی پرسید."),
            StoryParagraph("'Beloved?' she said. 'Where is Beloved?'", "گفت: «دلبند؟ دلبند کجاست؟»"),
            StoryParagraph("'She is gone,' Denver said, gently. 'She is gone, Mama. She is not coming back.'", "دنور لطیف گفت: «رفته. رفته، مامان. برنمی‌گردد.»"),
            StoryParagraph("And Sethe closed her eyes, and she wept, and she did not know whether she was weeping for joy or for sorrow, whether she was weeping for what she had lost or for what she had gained.", "و ست چشمانش را بست و گریست و نمی‌دانست برای شادی گریه می‌کند یا اندوه، برای آنچه از دست داده یا آنچه به دست آورده."),
            StoryParagraph("And the women stood around her, and they held her, and they sang to her, and they brought her back to life.", "و زنان دورش ایستادند و نگهش داشتند و برایش خواندند و به زندگی بازگرداندنش."),
            StoryParagraph("And so Beloved, the ghost, the daughter, the past made flesh, was finally gone.", "و اینگونه دلبند، روح، دختر، گذشته جسم‌گرفته، سرانجام رفت."),
            StoryParagraph("But her story would never be forgotten; her story would be told and retold, for generations, for centuries, forever.", "اما داستانش هرگز فراموش نمی‌شد؛ داستانش گفته و بازگو می‌شد، برای نسل‌ها، برای قرن‌ها، برای همیشه."),
            StoryParagraph("For Beloved was not just a ghost; she was the memory of slavery, the memory of suffering, the memory of everything that had been done and everything that had been lost.", "زیرا دلبند تنها روحی نبود؛ خاطره بردگی بود، خاطره رنج، خاطره هر چیزی که انجام شده بود و هر چیزی که از دست رفته بود."),
            StoryParagraph("And she would not be forgotten; she could not be forgotten; she must not be forgotten.", "و فراموش نمی‌شد؛ نمی‌توانست فراموش شود؛ نباید فراموش می‌شد."),
            StoryParagraph("For to forget her would be to forget the past; and to forget the past would be to risk repeating it.", "زیرا فراموش کردنش فراموش کردن گذشته بود؛ و فراموش کردن گذشته به خطر تکرارش می‌ارزید.")
        )
    )

    // ─────────── فصل ۵: شفا ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Healing", titlePersian = "شفا",
        paragraphs = listOf(
            StoryParagraph("Sethe did not recover quickly; she had given everything to Beloved, and she had nothing left.", "ست به‌سرعت بهبود نیافت؛ همه چیز به دلبند داده بود و چیزی برایش نمانده بود."),
            StoryParagraph("She lay in bed for weeks, too weak to move, too tired to eat, too sad to speak.", "هفته‌ها در تخت دراز کشید، بسیار ضعیف که نمی‌توانست حرکت کند، بسیار خسته که نمی‌توانست بخورد، بسیار غمگین که نمی‌توانست صحبت کند."),
            StoryParagraph("Denver took care of her, as Sethe had once taken care of Denver; Denver fed her, bathed her, held her, loved her.", "دنور از او مراقبت کرد، همانطور که ست یک بار از دنور مراقبت کرده بود؛ دنور غذا داد، شستش، در آغوشش گرفت، دوستش داشت."),
            StoryParagraph("And slowly, slowly, Sethe began to heal.", "و آهسته، آهسته، ست شروع کرد به شفا یافتن."),
            StoryParagraph("She began to eat again; she began to sit up; she began to walk around the room.", "دوباره شروع کرد به خوردن؛ شروع کرد به نشستن؛ شروع کرد به قدم زدن در اتاق."),
            StoryParagraph("She began to think about the past, and about the future, and about what she had done and what she had lost.", "شروع کرد به فکر کردن درباره گذشته و آینده و آنچه کرده بود و آنچه از دست داده بود."),
            StoryParagraph("And she began to understand something that she had never understood before: that she was her own best thing.", "و شروع کرد به فهمیدن چیزی که هرگز قبلاً نفهمیده بود: که خودش بهترین چیز خودش است."),
            StoryParagraph("She had given everything to her children, to Beloved, to Denver, to the sons who had run away; she had sacrificed herself for them, over and over.", "همه چیز به بچه‌هایش داده بود، به دلبند، به دنور، به پسرانی که فرار کرده بودند؛ خودش را برای آنان فدا کرده بود، بارها و بارها."),
            StoryParagraph("And she had believed that this was right, that this was what a mother should do, that this was the only way to be."),
            StoryParagraph("But she had forgotten something; she had forgotten that she too was a person, that she too deserved love, that she too deserved to live.", "اما چیزی فراموش کرده بود؛ فراموش کرده بود که خودش هم انسانی است، خودش هم سزاوار عشق است، خودش هم سزاوار زندگی است."),
            StoryParagraph("And now, in the quiet of the house, in the aftermath of Beloved, she began to remember.", "و حالا، در سکوت خانه، در پس‌آیند دلبند، شروع کرد به یاد آوردن."),
            StoryParagraph("Paul D returned one day, in the early spring, when the snow had melted and the ground was beginning to soften.", "پاول دی یک روز بازگشت، در اوایل بهار، وقتی برف آب شده بود و زمین شروع کرده بود به نرم شدن."),
            StoryParagraph("He came up the path, and he knocked on the door, and he waited.", "در مسیر بالا آمد و در زد و منتظر ماند."),
            StoryParagraph("Denver opened the door, and when she saw him, she did not know whether to be angry or glad.", "دنور در را باز کرد و وقتی دیدش، نمی‌دانست عصبانی باشد یا خوشحال."),
            StoryParagraph("'I have come back,' Paul D said, 'if you will have me.'", "پاول دی گفت: «بازگشته‌ام، اگر مرا بخواهید.»"),
            StoryParagraph("Denver said nothing; she simply stepped aside, and let him enter.", "دنور چیزی نگفت؛ تنها کنار رفت و گذاشت وارد شود."),
            StoryParagraph("Sethe was sitting in the kitchen, at the table, drinking tea; she looked up when Paul D came in, and her eyes were tired and sad.", "ست در آشپزخانه، سر میز نشسته بود، چای می‌نوشید؛ وقتی پاول دی وارد شد سر بلند کرد و چشمانش خسته و غمگین بودند."),
            StoryParagraph("'Sethe,' Paul D said, and his voice was soft.", "پاول دی گفت: «ست.» و صدایش لطیف بود."),
            StoryParagraph("'Paul D,' she said, and her voice was soft too.", "گفت: «پاول دی.» و صدایش هم لطیف بود."),
            StoryParagraph("They looked at each other for a long moment, and then Paul D sat down across from her, and he took her hand.", "مدت طولانی نگاه هم کردند و بعد پاول دی روبرویش نشست و دستش را گرفت."),
            StoryParagraph("'I have been thinking about you,' he said. 'I have been thinking about us.'", "گفت: «به تو فکر می‌کردم. به ما فکر می‌کردم.»"),
            StoryParagraph("'There is no us,' Sethe said. 'There never was.'", "ست گفت: «ما نیستیم. هرگز نبود.»"),
            StoryParagraph("'There could be,' Paul D said. 'There could be.'", "پاول دی گفت: «می‌تواند باشد. می‌تواند باشد.»"),
            StoryParagraph("Sethe shook her head; she did not believe him; she did not believe in anything anymore.", "ست سر تکان داد؛ باورش نکرد؛ دیگر به هیچ چیز باور نداشت."),
            StoryParagraph("'I am tired,' she said. 'I am tired of losing, of losing everyone I have ever loved. I do not want to lose anyone again.'", "گفت: «خسته‌ام. از باختن خسته‌ام، از از دست دادن هر کسی که هرگز دوست داشته‌ام. نمی‌خواهم دوباره کسی را از دست بدهم.»"),
            StoryParagraph("'You will not lose me,' Paul D said. 'I promise. I will not leave you.'", "پاول دی گفت: «مرا از دست نمی‌دهی. قول می‌دهم. ترکت نمی‌کنم.»"),
            StoryParagraph("'You cannot promise that,' Sethe said. 'No one can promise that. People leave. People die. People disappear.'", "ست گفت: «نمی‌توانی قول بدهی. هیچ‌کس نمی‌تواند قول بدهی. مردم می‌روند. مردم می‌میرند. مردم ناپدید می‌شوند.»"),
            StoryParagraph("'I know,' Paul D said. 'But I can promise to try. I can promise to stay as long as I can. I can promise to love you while I am here.'", "پاول دی گفت: «می‌دانم. اما می‌توانم قول بدهم تلاش کنم. می‌توانم قول بدهم تا آنجا که می‌توانم بمانم. می‌توانم قول بدهم تا وقتی اینجام دوستت بدارم.»"),
            StoryParagraph("And Sethe looked at him, and something in her face changed; something hard began to soften; something broken began to heal.", "و ست نگاهش کرد و چیزی در چهره‌اش تغییر کرد؛ چیزی سخت شروع کرد به نرم شدن؛ چیزی شکسته شروع کرد به شفا یافتن."),
            StoryParagraph("'You are good,' she said, quietly. 'You are good, Paul D. And I do not deserve you.'", "آرام گفت: «خوبی. خوبی، پاول دی. و سزاوار تو نیستم.»"),
            StoryParagraph("'You deserve everything,' Paul D said. 'You deserve love. You deserve peace. You deserve to live.'", "پاول دی گفت: «سزاوار همه چیز هستی. سزاوار عشق. سزاوار آرامش. سزاوار زندگی.»"),
            StoryParagraph("And Sethe wept, then, at last, in the kitchen of her house, in the arms of a man who loved her; she wept for Beloved, for Halle, for Baby Suggs, for herself.", "و ست گریست، آن وقت، سرانجام، در آشپزخانه خانه‌اش، در آغوش مردی که دوستش داشت؛ برای دلبند گریست، برای هال، برای بیبی ساگز، برای خودش."),
            StoryParagraph("And when the tears had stopped, when the weeping was over, she looked up, and she smiled, a small smile, a tentative smile, but a smile nonetheless.", "و وقتی اشک‌ها ایستادند، وقتی گریه تمام شد، سر بلند کرد و لبخند زد، لبخندی کوچک، لبخندی تردیدآمیز، اما به‌هرحال لبخند."),
            StoryParagraph("'You are my best thing,' she said to Paul D. 'And I am my own best thing. I am learning that, at last.'", "به پاول دی گفت: «تو بهترین چیز منی. و من بهترین چیز خودمم. سرانجام دارم این را یاد می‌گیرم.»"),
            StoryParagraph("And Paul D kissed her, gently, and held her, and knew that they had come, at last, to the beginning of something new.", "و پاول دی لطیف بوسیدش و نگهش داشت و دانست که سرانجام به آغاز چیزی نو رسیده بودند."),
            StoryParagraph("And so Sethe began to heal; so she began to love again; so she began to live again.", "و اینگونه ست شروع کرد به شفا یافتن؛ شروع کرد به عشق ورزیدن دوباره؛ شروع کرد به زندگی دوباره."),
            StoryParagraph("Not perfectly, not completely, not ever entirely; the wounds of slavery do not heal so easily, so fully, so finally.", "نه بی‌نقص، نه کاملاً، نه هرگز به‌طور کامل؛ زخم‌های بردگی اینقدر آسان شفا نمی‌یابند، اینقدر کامل، اینقدر نهایی."),
            StoryParagraph("But she began; and beginning was enough; beginning was everything.", "اما شروع کرد؛ و شروع کافی بود؛ شروع همه چیز بود."),
            StoryParagraph("And she was not alone; she had Denver, and she had Paul D, and she had the community that had finally welcomed her back.", "و تنها نبود؛ دنور را داشت و پاول دی را و جامعه‌ای را که سرانجام به آغوش بازش پذیرفته بود."),
            StoryParagraph("And she had the memory of Beloved, the daughter she had loved, the daughter she had lost, the daughter she would never forget.", "و خاطره دلبند را داشت، دختری که دوست داشته بود، دختری که از دست داده بود، دختری که هرگز فراموش نمی‌کرد."),
            StoryParagraph("She would carry Beloved with her always, in her heart, in her soul; but she would also live, and love, and hope.", "دلبند را همیشه با خود حمل می‌کرد، در قلبش، در روحش؛ اما همچنین زندگی می‌کرد و عشق می‌ورزید و امید داشت.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Beloved, published in 1987, is one of the greatest American novels of the twentieth century, and it won the Pulitzer Prize for Fiction.", "دلبند، منتشرشده در ۱۹۸۷، یکی از بزرگ‌ترین رمان‌های آمریکایی قرن بیستم است و جایزه پولیتزر برای داستان را برد."),
            StoryParagraph("It is based on a true story, the story of Margaret Garner, a slave woman who escaped from Kentucky and, when she was about to be recaptured, killed her own daughter.", "بر اساس داستانی راستین است، داستان مارگارت گارنر، زن برده‌ای که از کنتاکی فرار کرد و وقتی در آستانه دستگیری بود، دختر خودش را کشت."),
            StoryParagraph("Toni Morrison took that story and transformed it into a novel that is both historical and mythical, both personal and universal.", "تونی موریسون آن داستان را گرفت و به رمانی تبدیل کرد که هم تاریخی و هم اساطیری است، هم شخصی و هم جهانی."),
            StoryParagraph("The novel is about slavery, and about its aftermath; about the wounds that slavery left on the Black body, the Black soul, the Black family.", "رمان درباره بردگی است و درباره پیامدهایش؛ درباره زخم‌هایی که بردگی بر بدن سیاه، روح سیاه، خانواده سیاه گذاشت."),
            StoryParagraph("It is about memory, and about the impossibility of forgetting; about how the past lives within us, and how it shapes everything we do.", "درباره حافظه است و درباره ناممکن بودن فراموش کردن؛ درباره اینکه چگونه گذشته درون ما زندگی می‌کند و چگونه هر کاری که می‌کنیم را شکل می‌دهد."),
            StoryParagraph("It is about motherhood, and about the impossible choices that slavery forced upon mothers; about the love that can kill, and the love that can save.", "درباره مادری است و درباره انتخاب‌های ناممکنی که بردگی بر مادران تحمیل کرد؛ درباره عشقی که می‌تواند بکشد و عشقی که می‌تواند نجات دهد."),
            StoryParagraph("It is about freedom, and about what freedom really means, and about the cost of it, and about what it takes to live in it.", "درباره آزادی است و درباره معنای واقعی آزادی و بهایش و آنچه برای زندگی در آن لازم است."),
            StoryParagraph("It is about community, and about how communities can both wound and heal; about how the Black community in Cincinnati both rejected Sethe and, at last, saved her.", "درباره جامعه است و درباره اینکه جوامع هم می‌توانند زخم بزنند و هم شفا دهند؛ درباره اینکه جامعه سیاه‌پوستان در سینسیناتی هم ست را طرد کرد و هم در نهایت نجاتش داد."),
            StoryParagraph("And it is about love, above all; about the many forms of love, and the many ways of loving, and the impossibility of ever fully expressing love.", "و بیش از همه درباره عشق است؛ درباره اشکال بسیاری از عشق و شیوه‌های بسیاری از عشق ورزیدن و ناممکن بودن هرگز کاملاً بیان کردن عشق."),
            StoryParagraph("The novel is written in a style that is both lyrical and fragmented, both beautiful and disturbing.", "رمان به سبکی نوشته شده که هم غنایی و هم تکه‌تکه است، هم زیبا و هم آشفته‌کننده."),
            StoryParagraph("It moves back and forth in time, from the present to the past and back again, without warning, without explanation.", "در زمان جلو و عقب می‌رود، از حال به گذشته و دوباره باز، بدون هشدار، بدون توضیح."),
            StoryParagraph("It shifts from one voice to another, from Sethe to Denver to Beloved, from first person to third person and back.", "از صدایی به صدای دیگر می‌رود، از ست به دنور به دلبند، از اول شخص به سوم شخص و باز."),
            StoryParagraph("It uses repetition, and silence, and rhythm, and song; it uses the language of the Black community, and the language of the Bible, and the language of ghosts.", "از تکرار و سکوت و ریتم و آواز استفاده می‌کند؛ از زبان جامعه سیاه‌پوستان استفاده می‌کند و از زبان انجیل و از زبان ارواح."),
            StoryParagraph("The result is a novel that is not easy to read, that demands patience and attention, that rewards the reader who is willing to be changed.", "نتیجه رمانی است که خواندنش آسان نیست، صبر می‌خواهد و توجه، خواننده‌ای را که مایل به تغییر کردن است پاداش می‌دهد."),
            StoryParagraph("At the center of the novel is Sethe, a woman who has suffered more than most, who has lost more than most, who has borne more than most.", "در مرکز رمان ست است، زنی که بیش از بیشتران رنج کشیده، بیش از بیشتران از دست داده، بیش از بیشتران تحمل کرده."),
            StoryParagraph("But Sethe is not a victim; she is a survivor; she is a woman of tremendous strength and tremendous love, and it is these qualities that make her unforgettable.", "اما ست قربانی نیست؛ بازمانده است؛ زنی با قدرتی عظیم و عشقی عظیم و این کیفیت‌ها همان چیزی است که او را فراموش‌ناشدنی می‌کند."),
            StoryParagraph("The other central character is Beloved, who is at once a ghost, a daughter, a young woman, and a symbol.", "شخصیت محوری دیگر دلبند است، که همزمان روحی است، دختری، زنی جوان و نمادی."),
            StoryParagraph("She is the ghost of the daughter Sethe killed; she is the memory of the daughter Sethe lost; she is slavery itself, returned from the dead, demanding to be acknowledged.", "او روح دختری است که ست کشت؛ خاطره دختری است که ست از دست داد؛ خود بردگی است، بازگشته از مردگان، طلبکار به رسمیت شناخته شدن."),
            StoryParagraph("Denver, the third central character, is the one who survives, the one who moves forward, the one who represents the future.", "دنور، شخصیت محوری سوم، کسی است که زنده می‌ماند، کسی که به جلو حرکت می‌کند، کسی که نماینده آینده است."),
            StoryParagraph("She is the bridge between the past and the future, between the dead and the living, between her mother's pain and her own hope.", "او پل میان گذشته و آینده است، میان مردگان و زندگان، میان درد مادرش و امید خودش."),
            StoryParagraph("The novel's central theme is the destruction and the survival of the Black family under slavery.", "مضمون محوری رمان نابودی و بقای خانواده سیاه‌پوست تحت بردگی است."),
            StoryParagraph("Slavery destroyed families, separated parents from children, husbands from wives, brothers from sisters.", "بردگی خانواده‌ها را نابود کرد، پدر و مادر را از بچه‌ها جدا کرد، شوهر را از همسر، برادر را از خواهر."),
            StoryParagraph("It treated Black people not as human beings but as property, not as mothers and fathers but as breeders, not as individuals but as commodities.", "با سیاه‌پوستان نه همچون انسان رفتار می‌کرد بلکه همچون مال، نه همچون مادر و پدر بلکه همچون پرورش‌دهنده، نه همچون افراد بلکه همچون کالا."),
            StoryParagraph("And yet, in spite of everything, Black families survived; Black love survived; Black life survived.", "و با این حال، به رغم همه چیز، خانواده‌های سیاه‌پوست زنده ماندند؛ عشق سیاه زنده ماند؛ زندگی سیاه زنده ماند."),
            StoryParagraph("Beloved is a testament to that survival, a celebration of that endurance, a memorial to all those who did not survive.", "دلبند شهادتی است بر آن بقا، جشنی برای آن تحمل، یادبودی برای همه کسانی که زنده نماندند."),
            StoryParagraph("The novel is also about the importance of remembering; about how the past must be faced, must be acknowledged, must be told.", "رمان همچنین درباره اهمیت به یاد آوردن است؛ درباره اینکه گذشته باید با آن روبرو شد، باید به رسمیت شناخت، باید گفت."),
            StoryParagraph("Because to forget is to betray; to forget is to risk repeating; to forget is to allow the wounds to fester.", "زیرا فراموش کردن خیانت است؛ فراموش کردن خطر تکرار است؛ فراموش کردن گذاشتن زخم‌ها به چرکیدن است."),
            StoryParagraph("And so Sethe must remember; and so Denver must remember; and so we, the readers, must remember.", "و بنابراین ست باید به یاد بیاورد؛ و دنور باید به یاد بیاورد؛ و ما، خوانندگان، باید به یاد بیاوریم."),
            StoryParagraph("We must remember slavery, and its horrors, and its victims; we must remember the slaves who died, and the slaves who survived, and the slaves who escaped.", "باید بردگی را به یاد بیاوریم و هولناکی‌هایش و قربانیانش؛ باید بردگانی را که مردند به یاد بیاوریم و بردگانی که زنده ماندند و بردگانی که فرار کردند."),
            StoryParagraph("We must remember, because their story is our story, because their pain is our pain, because their survival is our survival.", "باید به یاد بیاوریم، چون داستانشان داستان ماست، چون دردشان درد ماست، چون بقایشان بقای ماست."),
            StoryParagraph("And yet, the novel is not without hope; it is not without love; it is not without the possibility of healing.", "و با این حال، رمان بدون امید نیست؛ بدون عشق نیست؛ بدون امکان شفا نیست."),
            StoryParagraph("Because Sethe does heal, in the end; because Denver does grow, does thrive, does live; because Paul D does love, does stay, does build.", "زیرا ست در پایان شفا می‌یابد؛ زیرا دنور رشد می‌کند، شکوفا می‌شود، زندگی می‌کند؛ زیرا پاول دی عشق می‌ورزد، می‌ماند، می‌سازد."),
            StoryParagraph("Because even after everything, even after slavery, even after death, life continues; love continues; hope continues.", "زیرا حتی بعد از همه چیز، حتی بعد از بردگی، حتی بعد از مرگ، زندگی ادامه می‌یابد؛ عشق ادامه می‌یابد؛ امید ادامه می‌یابد."),
            StoryParagraph("And that, perhaps, is the deepest meaning of the novel: that life is stronger than death, that love is stronger than hate, that hope is stronger than despair.", "و این، شاید، عمیق‌ترین معنای رمان است: زندگی از مرگ قوی‌تر است، عشق از نفرت، امید از ناامیدی."),
            StoryParagraph("Beloved is a novel of terrible beauty, of profound sadness, of infinite love.", "دلبند رمانی است با زیبایی هولناک، اندوه عمیق، عشق بی‌نهایت."),
            StoryParagraph("It is a novel that must be read, must be felt, must be remembered; a novel that demands everything from its reader, and gives back even more.", "رمانی است که باید خوانده شود، باید حس شود، باید به یاد آورده شود؛ رمانی که همه چیز از خواننده‌اش می‌طلبد و بیشتر پس می‌دهد."),
            StoryParagraph("It is a novel that reminds us of what we have been, and of what we can become; of the depths to which we can sink, and of the heights to which we can rise.", "رمانی است که یادآوری‌مان می‌کند چه بوده‌ایم و چه می‌توانیم بشویم؛ به چه عمقی می‌توانیم فرو رویم و به چه بلندی می‌توانیم برخاست."),
            StoryParagraph("It is a novel about Black people, written by a Black woman, for all people; a novel that belongs to everyone, and that no one should forget.", "رمانی است درباره سیاه‌پوستان، نوشته‌شده توسط زنی سیاه‌پوست، برای همه مردم؛ رمانی که متعلق به همه است و هیچ‌کس نباید فراموشش کند."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of Beloved is not finished; it is being written every day, in every life, in every heart.", "زیرا داستان دلبند تمام نشده؛ هر روز نوشته می‌شود، در هر زندگی، در هر قلب."),
            StoryParagraph("And it will not be finished until the wounds of slavery are healed, until the memory of slavery is honored, until love has finally overcome hate.", "و تمام نمی‌شود تا زخم‌های بردگی شفا یابند، تا خاطره بردگی محترم شمرده شود، تا عشق سرانجام بر نفرت چیره شود.")
        )
    )
}